import "./Nav.css";

function Nav() {
  return (
    <div className="main">
      <form action="">
        <input className="inputArea" type="text" placeholder="Name" />
        <input className="inputArea" type="text" placeholder="Surename" />
        <input className="inputArea" type="text" placeholder="Login" />
        <input className="inputArea" type="password" placeholder="Password" />
        <input className="submitBtn" type="submit" />
      </form>
    </div>
  );
}

export default Nav;
